    pairs=[]; var={}
    for i in range(n):
        for j in range(i+1,n):
            if colors[i]!=colors[j]:
                var[(i,j)] = Bool(f'e_{i}_{j}')
                pairs.append((i,j))
    def E(i,j):
        if i>j: i,j=j,i
        if i==j or colors[i]==colors[j]: return False
        return var[(i,j)]
    s=Solver()
