def lcf(n, seq, reps):
    edges=set()
    for i in range(n):
        a,b=i,(i+1)%n
        if a>b:a,b=b,a
        edges.add((a,b))
    arr=seq*reps
    for i,s in enumerate(arr):
        j=(i+s)%n
        a,b=i,j
        if a>b:a,b=b,a
        edges.add((a,b))
    return edges

def girth(n,edges):
    adj=[[] for _ in range(n)]
    for a,b in edges: adj[a].append(b); adj[b].append(a)
    best=10**9
    from collections import deque
    for s in range(n):
        dist=[-1]*n; par=[-1]*n; dist[s]=0
        q=deque([s])
        while q:
            v=q.popleft()
            for w in adj[v]:
                if dist[w]<0:
                    dist[w]=dist[v]+1; par[w]=v; q.append(w)
                elif par[v]!=w and par[w]!=v:
                    best=min(best, dist[v]+dist[w]+1)
    return best
